import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cpp_decl = r"""
#include <torch/extension.h>

torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__global__ void cute_matvec_kernel(
    const float* __restrict__ A,
    const float* __restrict__ B,
    float* __restrict__ C,
    int M,
    int K)
{
    const int row = blockIdx.x;
    const int tid = threadIdx.x;

    if (row >= M) {
        return;
    }

    Tensor gA = make_tensor(
        make_gmem_ptr(A + static_cast<long long>(row) * K),
        make_shape(K),
        make_stride(Int<1>{}));

    Tensor gB = make_tensor(
        make_gmem_ptr(B),
        make_shape(K),
        make_stride(Int<1>{}));

    float sum = 0.0f;

    for (int k = tid; k < K; k += blockDim.x) {
        sum = fmaf(gA(k), gB(k), sum);
    }

    __shared__ float reduction[256];
    reduction[tid] = sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride >= 32; stride >>= 1) {
        if (tid < stride) {
            reduction[tid] += reduction[tid + stride];
        }
        __syncthreads();
    }

    if (tid < 32) {
        float value = reduction[tid];

        #pragma unroll
        for (int offset = 16; offset > 0; offset >>= 1) {
            value += __shfl_down_sync(0xffffffff, value, offset);
        }

        if (tid == 0) {
            C[row] = value;
        }
    }
}

torch::Tensor cute_matvec(torch::Tensor A, torch::Tensor B)
{
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    TORCH_CHECK(A.scalar_type() == at::kFloat, "A must be float32");
    TORCH_CHECK(B.scalar_type() == at::kFloat, "B must be float32");
    TORCH_CHECK(B.size(1) == 1, "B must have shape (K, 1)");
    TORCH_CHECK(A.size(1) == B.size(0), "Incompatible matrix dimensions");

    auto A_contiguous = A.contiguous();
    auto B_contiguous = B.contiguous();

    const int M = static_cast<int>(A_contiguous.size(0));
    const int K = static_cast<int>(A_contiguous.size(1));

    auto C = torch::empty({M, 1}, A_contiguous.options());

    constexpr int threads = 256;
    const dim3 grid(M);
    const dim3 block(threads);

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    cute_matvec_kernel<<<grid, block, 0, stream>>>(
        A_contiguous.data_ptr<float>(),
        B_contiguous.data_ptr<float>(),
        C.data_ptr<float>(),
        M,
        K);

    TORCH_CHECK(
        cudaGetLastError() == cudaSuccess,
        "CUTE matrix-vector kernel launch failed");

    return C;
}
"""

cute_ext = load_inline(
    name="cute_matvec_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["cute_matvec"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=[
        "-O3",
        "-I/root/cutegen_test/cutegen/cutlass/include",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self._ext = cute_ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        return self._ext.cute_matvec(A, B)

